def width_rows(table):
    return [[f"{length}mm"] + [f"{w}mm" for w in widths] for length, *widths in table]


def inch_mm(s):
    """'10 5/16' 같은 인치 표기를 mm 정수로."""
    return round(sum(Fraction(x) for x in str(s).split()) * Fraction("25.4"))


def foot_rows():
    return [[f"{mm}mm", "·".join(str(inch_mm(v)) for v in NIKE_FOOT_IN[mm]) + "mm",
             f"{round(ADIDAS_FOOT_CM[mm] * 10)}mm", f"{mm}mm"] for mm in range(225, 305, 5)]


def models_of(brand):
    return [m for m in MODELS if m["name"].split()[0] == brand]


def link(m):
    return f'<a href="/{m["slug"]}/">{m["name"]}</a>'


def hub_sub(brand):
    n = len(models_of(brand))
    return f"공식 환산 · 모델 {n}개" if n else "공식 환산"


def hub(brand, caption, extra=(), **text):
    """브랜드 사이즈표 페이지. 환산표·모델 목록·결론 숫자는 데이터에서 만들고, 설명 문구만 손으로 쓴다.
    공식표에 없는 칸(모든 줄이 —)은 빼고, 모델이 없는 브랜드는 모델 표를 싣지 않는다."""
    chart, ms = dict(BRANDS).get(brand) or BRAND_CHARTS[brand][0], models_of(brand)
    label = BRAND_LABEL.get(brand, brand)
    us, _, uk, eu = chart[270]
    cols = [i for i in range(4) if any(v[i] != "—" for v in chart.values())]
    model_table = {"h2": f"{label} 모델별 권장 사이즈",
                   "intro": "평소 신는 사이즈 기준입니다. 모델을 누르면 발볼별 가이드와 근거를 볼 수 있습니다.",
                   "caption": "권장 사이즈는 착용 경향이며 발볼·발등에 따라 달라질 수 있습니다.",
                   "head": ["모델", "권장 사이즈"], "rows": [[link(m), m["verdict"]] for m in ms], "highlight": 0}
    return {
        "slug": BRAND_HUBS[brand], "name": f"{label} 사이즈표",
        "title": f"{label} 사이즈표 — mm·US·UK·EU 공식 환산과 모델별 권장 사이즈",
        "eyebrow": f"{label} 공식표" + (f" · 모델 {len(ms)}개" if ms else ""),
        "h1": f"{label} 사이즈표와 <em>모델별 권장 사이즈</em>",
        "verdict_top": "핵심",
        "verdict": f"270mm = US {num(us)} = UK {num(uk)} = EU {num(eu)}",
        "tables": [
            {"h2": f"{label} 공식 사이즈표",
             "intro": "왼쪽 mm는 상자에 적히는 한국 표기입니다. 같은 줄에서 US·UK·EU를 읽으면 됩니다.",
             "caption": caption, "head": ["KR 표기"] + [["US 남성", "US 여성", "UK", "EU"][i] for i in cols],
             "rows": [[f"{mm}mm"] + [num(chart[mm][i]) for i in cols] for mm in sorted(chart)], "highlight": 0},
            *([model_table] if ms else []),
            *extra,
        ],
        "related_h2": "다른 브랜드 사이즈표",
        "related": [(f"/{s}/", f"{BRAND_LABEL.get(b, b)} 사이즈표", hub_sub(b))
                    for b, s in BRAND_HUBS.items() if b != brand]
                   + [("/foot-length-chart/", "발 길이로 사이즈 찾기", "브랜드 공식표의 발 길이"),
                      ("/womens-size/", "우먼스 사이즈", "남자가 W 상품을 살 때")],
        "note": "브랜드 공식표는 바뀔 수 있으니, 구매 전 상품 페이지의 사이즈 표기를 한 번 더 확인하시기 바랍니다.",
        **text,
    }


def women_table(brand, chart_w, chart, caption, intro):
    """여성 전용 상품표. KR mm -> (US 여성, EU)."""
    return {"h2": f"{brand} 여성 전용 상품 사이즈표", "intro": intro, "caption": caption,
            "head": ["KR 표기", "여성 전용 US", "여성 전용 EU", "남녀공용 US 여성"],
            "rows": [[f"{mm}mm", num(chart_w[mm][0]), num(chart_w[mm][1]), num(chart.get(mm, ("—",) * 4)[1])]
                     for mm in sorted(chart_w)], "highlight": 0}


