TRIUMPH_CUP = [("AA", "AA", "AA"), ("A", "A", "A"), ("B", "B", "B"), ("C", "C", "C"), ("D", "D", "D"),
               ("E", "DD", "DD"), ("F", "E", "DDD"), ("G", "F", "G")]
