# 브라 계산기: 밴드는 트라이엄프 밑가슴 구간(비비안 표가 있는 70~90만), 컵은 차이가 가장 가까운 비비안 단계.
# 표가 정적 HTML에 있으므로 JS가 꺼지면 숨겨 둔다.
BRA_BANDS = [[*map(int, r.split("~")), e, u, f] for r, e, u, f in TRIUMPH_BAND if 70 <= e <= 90]
BRA_TOOL = """
  <section id="braTool" hidden>
    <h2>브라 사이즈 계산기</h2>
    <p>줄자로 잰 밑가슴과 윗가슴을 넣으세요. 이 페이지의 비비안·트라이엄프 공식표로 계산합니다.</p>
    <div class="entry">
      <label for="braUnder">밑가슴(cm)</label>
      <input id="braUnder" type="number" inputmode="decimal" min="60" max="100" step="any" placeholder="75">
    </div>
    <div class="entry">
      <label for="braOver">윗가슴(cm)</label>
      <input id="braOver" type="number" inputmode="decimal" min="65" max="130" step="any" placeholder="87.5">
    </div>
    <div aria-live="polite">
      <p class="ring-out" id="braOut"></p>
      <p id="braWhy"></p>
    </div>
  </section>
"""
BRA_SCRIPT = """<script>
(function(){
  var tool=document.getElementById("braTool");
  if(!tool) return;
  tool.hidden=false;
  var B=""" + json.dumps(BRA_BANDS) + """, C=""" + json.dumps(VIVIEN_CUP) + """;
  var under=document.getElementById("braUnder"), over=document.getElementById("braOver");
  var out=document.getElementById("braOut"), why=document.getElementById("braWhy");
  function fmt(x){ return String(Math.round(x*10)/10); }
  function show(){
    var u=parseFloat(under.value), o=parseFloat(over.value), b=null, r=Math.round(u);
    out.textContent=""; why.textContent="";
    if(!(u>0)||!(o>0)) return;
    B.forEach(function(x){ if(r>=x[0]&&r<=x[1]) b=x; });
    if(!b){ why.textContent="밑가슴 "+B[0][0]+"~"+B[B.length-1][1]+"cm만 계산합니다(비비안 공식표 밴드 70~90)."; return; }
    var d=Math.round((o-u)*10)/10, k=Math.round((d-C[0][1])/2.5);
    if(k<0||k>=C.length){ why.textContent="윗가슴 − 밑가슴 "+fmt(d)+"cm는 비비안 공식표 범위("+C[0][1]+"~"+C[C.length-1][1]+"cm) 밖입니다."; return; }
    var c=C[k];
    out.textContent=b[2]+c[0];
    why.textContent="밴드 "+b[2]+": 트라이엄프 공식표에서 밑가슴 "+b[0]+"~"+b[1]+"cm가 "+b[2]+"입니다"+(r!==u?"("+fmt(u)+"cm는 반올림해 "+r+"cm)":"")+". "
      +"컵 "+c[0]+": 차이 "+fmt(d)+"cm"+(d===c[1]?"로 비비안 공식표 그대로입니다. ":"가 비비안 공식표의 "+fmt(c[1])+"cm에 가장 가깝습니다. ")
      +"해외 밴드는 영국·미국 "+b[3]+", 프랑스 "+b[4]+"입니다. 해외 컵은 브랜드마다 기준이 달라, 윗가슴 cm로 그 브랜드 표에서 다시 고르세요.";
  }
  under.addEventListener("input",show);
  over.addEventListener("input",show);
})();
</script>
"""

